// MIPS32 Register file (32 registers + HI/LO)
class MIPSRegisters {
  constructor() {
    this.reg = new Uint32Array(32);
    this.hi = 0;
    this.lo = 0;
    this.pc = 0;
    this.loAddress = 0; // Address to store return values
  }

  read(reg) {
    return this.reg[reg] || 0;
  }

  write(reg, value) {
    this.reg[reg] = value >>> 0;
  }

  getPc() { return this.pc; }
  setPc(value) { this.pc = value >>> 0; }
