// Memory class for MIPS
class MIPSMemory {
  constructor(size = 32 * 1024 * 1024) { // 32MB default
    this.memory = new Uint8Array(size);
    this.dataView = new DataView(this.memory.buffer);
  }

  readUint32(addr) {
    if (addr + 4 > this.memory.length) return 0;
    return this.dataView.getUint32(addr, true); // Little endian (MIPS can be either)
  }

  writeUint32(addr, value) {
    if (addr + 4 > this.memory.length) return;
    this.dataView.setUint32(addr, value >>> 0, true);
  }

  readUint16(addr) {
    if (addr + 2 > this.memory.length) return 0;
    return this.dataView.getUint16(addr, true);
  }

  writeUint16(addr, value) {
    if (addr + 2 > this.memory.length) return;
    this.dataView.setUint16(addr, value, true);
  }

  readInt32(addr) {
    if (addr + 4 > this.memory.length) return 0;
    return this.dataView.getInt32(addr, true);
  }

  writeInt32(addr, value) {
    if (addr + 4 > this.memory.length) return;
    this.dataView.setInt32(addr, value, true);
  }

  readBytes(addr, count) {
    return this.memory.slice(addr, addr + count);
  }

  writeBytes(addr, data) {
    this.memory.set(data, addr);
  }

  readString(addr, maxLength = 256) {
    let result = '';
    for (let i = 0; i < maxLength; i++) {
      const b = this.memory[addr + i];
      if (b === 0) break;
      result += String.fromCharCode(b);
    }
    return result;
  }
}

// ELF Parser for MIPS32
class ELFParser {
  constructor(buffer) {
    this.buffer = buffer;
    this.dataView = new DataView(buffer);
  }

  parse() {
    // ELF Header (52 bytes for 32-bit)
    const magic = this.buffer[0:4];
    if (magic !== '\x7fELF') {
      throw new Error('Not an ELF file');
    }

    const eiClass = this.buffer[4];
    const eiData = this.buffer[5];
    const eiVersion = this.buffer[6];

    const type = this.readUint16(16);
    const machine = this.readUint16(18);
    const version = this.readUint32(20);
    const entry = this.readUint32(24);
    const phoff = this.readUint32(28);
    const shoff = this.readUint32(32);
    const flags = this.readUint32(36);
    const ehsize = this.readUint16(40);
    const phentsize = this.readUint16(42);
    const phnum = this.readUint16(44);
    const shentsize = this.readUint16(46);
    const shnum = this.readUint16(48);
    const shstrndx = this.readUint16(50);

    return {
      entry,
      phoff,
      shoff,
      phnum,
      phentsize,
      machine,
      segments: []
    };
  }

  readUint16(offset) {
    return this.dataView.getUint16(offset, true);
  }

  readUint32(offset) { // Little endian
    return this.dataView.getUint32(offset, true);
  }

  readInt32(offset) {
    return this.dataView.getInt32(offset, true);
  }

  parseProgramHeaders(phoff, phentsize, phnum) {
    const segments = [];

    for (let i = 0; i < phnum; i++) {
      const off = phoff + i * phentsize;

      const segment = {
        type: this.readUint32(off),
        offset: this.readUint32(off + 4),
        vaddr: this.readUint32(off + 8),
        paddr: this.readUint32(off + 12),
        filesz: this.readUint32(off + 16),
        memsz: this.readUint32(off + 20),
        flags: this.readUint32(off + 24),
        align: this.readUint32(off + 28)
      };

      segments.push(segment);
    }

    return segments;
  }
}

