        return 1;

      default:
        console.log(`Unknown syscall: ${syscallNum}`);
        return;
    }
  }

  // Helper to write a BMP file from screen buffer
  saveFrameAsBMP(buffer, width, height, frameNum) {
    const filename = `frame_${frameNum.toString().padStart(4, '0')}.bmp`;

    // BMP file header (14 bytes)
    const fileHeader = Buffer.alloc(14);
    const fileSize = 54 + width * height * 4; // Header + padding + pixel data

    fileHeader.writeUInt8(0x42, 0); // 'B'
    fileHeader.writeUInt8(0x4D, 1); // 'M'
    fileHeader.writeUInt32LE(fileSize, 2); // File size
    fileHeader.writeUInt16LE(0, 6); // Reserved
    fileHeader.writeUInt16LE(0, 8); // Reserved
    fileHeader.writeUInt32LE(54, 10); // Pixel data offset

    // DIB header (40 bytes for BITMAPINFOHEADER)
    const dibHeader = Buffer.alloc(40);
    dibHeader.writeUInt32LE(40, 0); // Header size
    dibHeader.writeInt32LE(width, 4); // Width
    dibHeader.writeInt32LE(height * 2, 8); // Height (negative for top-down)
    dibHeader.writeUInt16LE(1, 12); // Planes
    dibHeader.writeUInt16LE(32, 14); // Bits per pixel
    dibHeader.writeUInt32LE(0, 16); // Compression (none)
    dibHeader.writeUInt32LE(width * height * 4, 20); // Image size
    dibHeader.writeUInt32LE(0, 24); // X pixels per meter
    dibHeader.writeUInt32LE(0, 28); // Y pixels per meter
    dibHeader.writeUInt32LE(0, 32); // Colors used
    dibHeader.writeUInt32LE(0, 36); // Important colors

    // Pixel data (BGRA format)
    const pixelData = Buffer.alloc(width * height * 4);

    // Convert from RGBA in memory to BGRA in BMP
    for (let i = 0; i < width * height * 4; i += 4) {
      const r = buffer[i];
      const g = buffer[i + 1];
      const b = buffer[i + 2];
      pixelData[i] = b;
      pixelData[i + 1] = g;
      pixelData[i + 2] = r;
      pixelData[i + 3] = 255; // Alpha
    }

    const bmp = Buffer.concat([fileHeader, dibHeader, pixelData]);
    const outPath = path.join(process.cwd(), filename);
    fs.writeFileSync(outPath, bmp);
    console.log(`Saved frame ${frameNum} to ${filename}`);

    return filename;
  }
}

