// Syscall handler
function handleSyscall(mem, regs) {
  const num = regs.r[2];
  const a0 = regs.r[4], a1 = regs.r[5], a2 = regs.r[6], a3 = regs.r[7];

  switch (num) {
    case 10: console.log('exit'); process.exit(0);
    case 4000:
      console.log('save_frame');
      saveBMP('frame.bmp', a1, a2, a3);
      break;
    case 4001:
      console.log('set_buffer', '0x' + a0.toString(16));
      break;
  }
}

// MIPS CPU
class CPU {
  constructor(binaryPath) {
    this.mem = new Memory();
    this.regs = new Regs();
    this.binaryPath = binaryPath;
  }

  load() {
    const data = fs.readFileSync(this.binaryPath);
    console.log('Loaded', data.length, 'bytes');
    if (data[0] !== 0x7f || data[1] !== 0x45 || data[2] !== 0x4c || data[3] !== 0x46)
      throw new Error('Not ELF');
    const entry = data.readUInt32LE(24);
    const phoff = data.readUInt32LE(28);
    const phentSize = data.readUInt16LE(42);
    const phnum = data.readUInt16LE(44);
    console.log('Entry: 0x' + entry.toString(16));
    let off = phoff;
    for (let i = 0; i < phnum; i++) {
      const type = data.readUInt32LE(off);
      const vaddr = data.readUInt32LE(off + 8);
      const foff = data.readUInt32LE(off + 12);
      const fsize = data.readUInt32LE(off + 16);
      if (type === 1) {
        console.log('Loading to 0x' + vaddr.toString(16));
        this.mem.data.set(data.slice(foff, foff + fsize), vaddr);
      }
      off += phentSize;
    }
    this.regs.pc = entry;
  }

  step() {
    const instr = this.mem.readU32(this.regs.pc);
    if (instr === 0) return false;
    const op = instr >>> 26;
    const rs = (instr >>> 21) & 31;
    const rt = (instr >>> 16) & 31;
    const imm16 = instr & 0xffff;

    if (op === 0 && (instr & 0x3f) === 0x0c) {
      handleSyscall(this.mem, this.regs);
      this.regs.pc += 4;
      return true;
    }

    if (op === 2) {
      this.regs.r[31] = this.regs.pc + 4;
      this.regs.pc = (instr & 0x03ffffff) << 2;
      return true;
    }

    if (op === 4) {
      if (this.regs.r[rs] === this.regs.r[rt]) this.regs.pc += imm16 << 2;
      else this.regs.pc += 4;
      return true;
    }

    if (op === 5) {
      if (this.regs.r[rs] !== this.regs.r[rt]) this.regs.pc += imm16 << 2;
      else this.regs.pc += 4;
      return true;
    }

    if (op === 9) {
      this.regs.r[rt] = (this.regs.r[rs] + imm16) >>> 0;
      this.regs.pc += 4;
      return true;
    }

    if (op === 35) {
      this.regs.r[rt] = this.mem.readU32(this.regs.r[rs] + imm16);
      this.regs.pc += 4;
      return true;
    }

    if (op === 43) {
      this.mem.writeU32(this.regs.r[rs] + imm16, this.regs.r[rt]);
      this.regs.pc += 4;
      return true;
    }

    if (op === 3) {
      this.regs.r[rt] = imm16 << 16;
      this.regs.pc += 4;
      return true;
    }

    if (op === 13) {
      this.regs.r[rt] = this.regs.r[rs] | imm16;
      this.regs.pc += 4;
      return true;
    }

    if (op === 0) {
      const funct = instr & 0x3f;
      switch (funct) {
        case 0x20: this.regs.r[rt] = this.regs.r[rs] + this.regs.r[rt]; break;
        case 0x21: this.regs.r[rt] = (this.regs.r[rs] + this.regs.r[rt]) >>> 0; break;
        case 0x22: this.regs.r[rt] = (this.regs.r[rs] - this.regs.r[rt]) >>> 0; break;
        case 0x24: this.regs.r[rt] = this.regs.r[rs] & this.regs.r[rt]; break;
        case 0x25: this.regs.r[rt] = this.regs.r[rs] | this.regs.r[rt]; break;
        case 0x27: this.regs.r[rt] = ~(this.regs.r[rs] | this.regs.r[rt]) >>> 0; break;
      }
      this.regs.pc += 4;
      return true;
    }

    console.log('Unknown opcode ' + op.toString(16));
    this.regs.pc += 4;
    return true;
  }

  run(maxInsts = 1000000) {
    let count = 0;
    while (count < maxInsts) {
      if (!this.step()) break;
      count++;
    }
    console.log('Executed', count, 'instructions');
  }
}

async function main() {
  const cpu = new CPU(process.argv[2] || '/app/doomgeneric_mips');
  cpu.load();
  console.log('Starting...');
  cpu.run(1000000);
}

